/**
 * Capital payback tracking — pure.
 * 4 owners × AED 40,000 = AED 160,000; target: all back within 12 months of trading start.
 *
 * "Recovered" is cumulative operating profit since trading start (cash generated by the business that
 * could be returned to owners). Distributions already paid are reported separately for information.
 */
import { addMonths, daysBetweenInclusive, addDays, type ISODate } from "./periods.js";

export interface PaybackInput {
  capitalFils: number;
  tradingStart: ISODate;
  targetMonths: number;
  asOf: ISODate;
  cumulativeOperatingProfitFils: number;
  distributedFils: number;
  /** Operating profit over the trailing window used for projection (e.g. last 28 days). */
  recentProfitFils: number;
  recentDays: number;
}

export interface PaybackStatus {
  capitalFils: number;
  recoveredFils: number;
  remainingFils: number;
  pctRecovered: number;
  targetDate: ISODate;
  daysElapsed: number;
  daysLeft: number;
  requiredPerMonthFils: number;          // original straight-line pace (capital / months)
  requiredPerMonthFromNowFils: number;   // what's needed from today to hit the target date
  recentPerMonthFils: number;            // trailing run-rate, scaled to 30.44 days
  projectedPaybackDate: ISODate | null;  // null if run-rate ≤ 0
  onTrack: boolean;
  distributedFils: number;
}

const DAYS_PER_MONTH = 365.25 / 12;

export function computePayback(i: PaybackInput): PaybackStatus {
  const targetDate = addDays(addMonths(i.tradingStart, i.targetMonths), -1); // 2026-10-08 + 12m − 1d = 2027-10-07
  const recovered = Math.max(0, i.cumulativeOperatingProfitFils);
  const remaining = Math.max(0, i.capitalFils - recovered);
  const daysElapsed = i.asOf < i.tradingStart ? 0 : daysBetweenInclusive(i.tradingStart, i.asOf);
  const daysLeft = i.asOf >= targetDate ? 0 : daysBetweenInclusive(i.asOf, targetDate) - 1;

  const recentPerDay = i.recentDays > 0 ? i.recentProfitFils / i.recentDays : 0;
  const recentPerMonth = Math.round(recentPerDay * DAYS_PER_MONTH);
  const requiredPerMonthFromNow =
    remaining === 0 ? 0 : daysLeft === 0 ? remaining : Math.round((remaining / daysLeft) * DAYS_PER_MONTH);

  let projected: ISODate | null = null;
  if (remaining === 0) projected = i.asOf;
  else if (recentPerDay > 0) projected = addDays(i.asOf, Math.ceil(remaining / recentPerDay));

  return {
    capitalFils: i.capitalFils,
    recoveredFils: recovered,
    remainingFils: remaining,
    pctRecovered: i.capitalFils === 0 ? 1 : recovered / i.capitalFils,
    targetDate,
    daysElapsed,
    daysLeft,
    requiredPerMonthFils: Math.round(i.capitalFils / i.targetMonths),
    requiredPerMonthFromNowFils: requiredPerMonthFromNow,
    recentPerMonthFils: recentPerMonth,
    projectedPaybackDate: projected,
    onTrack: projected !== null && projected <= targetDate,
    distributedFils: i.distributedFils,
  };
}
